    private int serial;
    public Part() {
        made++;
        serial = made;
    }
    public int getSerial() {
        return serial;
    }
    public static int getMade() {
        return made;
    }
}

class SubPart extends Part {
    public SubPart() {
        super();
    }
    public SubPart(int k) {
        this();
        for (int i = 0; i < k; i++)
